INSERT INTO public.work (id, code, source, location, name, unit, volume, weight, work_type, executor_type, responsible_id, subcontractor_id, status, criticality, comment, section, source_row_ref, fact_pct, fact_pct_raw, data_quality_flag, data_quality_note, created_at, updated_at, volume_raw, gesn_norm_id, ssr_norm_id, plan_finish_date, id_package_id, change_id, prescription_id, amount_rub_with_vat) OVERRIDING SYSTEM VALUE VALUES (258, 'TM35-RSK-002', 'aux', 'УУТЭ1', '№ 376 УУТЭ1, УУТЭ2. На смонтированных металлических гильзах проходов трубопроводов через стены узлов учета тепловой энергии  (УУТЭ1, УУТЭ2) не выполнено антикоррозионное покрытие. Нарушены    требования    проектной документации: л.59 шифр 2020.069.3000-ТМ-ИЛО.АС.ГЧ; ч. 6 ст. 52 ГрК РФ.', 'шт', 1.0, NULL, NULL, 'own_forces', NULL, NULL, 'done_physically', NULL, NULL, 'Работы по устранению выявленных недостатков при строительстве', 'График по замечаниям РСК!7', 100.0, '100', 'needs_review', '«Наименование работ» пусто (D7), использовано «Содержание работы» — сверить с ПТО ИКС', '2026-08-14 16:02:23.527025+00', '2026-08-29 00:17:41.891731+00', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.work (id, code, source, location, name, unit, volume, weight, work_type, executor_type, responsible_id, subcontractor_id, status, criticality, comment, section, source_row_ref, fact_pct, fact_pct_raw, data_quality_flag, data_quality_note, created_at, updated_at, volume_raw, gesn_norm_id, ssr_norm_id, plan_finish_date, id_package_id, change_id, prescription_id, amount_rub_with_vat) OVERRIDING SYSTEM VALUE VALUES (261, 'TM35-RSK-005', 'aux', 'УП8', 'Участок УП8-УТП10. На участке ОПв1.4-ОПн1.6 скользящие опоры приварены к опорным частям эстакады. В результате этого, при наполнении  трубопроводов Т1, Т2 теплоносителем произошло смещение трубопровода Т1 относительно продольной оси теплотрассы. На участке УП9-УП10  выявлено  неполное прилегание скользящих опор трубопроводов Т1, Т2 к опорным частям эстакады. Нарушены требования проектной документации  л.32 шифр  2020.069.3000-ТМ-ТКР-ГЧ; п. 5.4.15 СП 74.13330.2023 «Тепловые сети»; ч. 6 ст. 52 ГрК РФ.', 'шт', 1.0, NULL, NULL, 'own_forces', NULL, NULL, 'done_physically', NULL, NULL, 'Работы по устранению выявленных недостатков при строительстве', 'График по замечаниям РСК!10', 100.0, '100', 'needs_review', '«Наименование работ» пусто (D10), использовано «Содержание работы» — сверить с ПТО ИКС', '2026-08-14 16:02:23.527025+00', '2026-08-29 00:17:41.891731+00', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
